export const listAdminLedger = async (params?: ListAdminLedgerParams, options?: Parameters<typeof customFetch>[1]): Promise<BankTransaction[]> => {

  return customFetch<BankTransaction[]>(getListAdminLedgerUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





